<?php
namespace App\Services;
use App\Models\{Account,Agency,JournalEntry,JournalLine}; use Illuminate\Support\Facades\DB;
class AccountingService {
 public function ensureDefaultAccounts(Agency $agency):void { $defs=[['1000','Cash','asset'],['1100','Bank','asset'],['1200','Accounts Receivable','asset'],['2000','Accounts Payable','liability'],['2100','Landlord Payable','liability'],['3000','Owner Capital','equity'],['4000','Sale Commission','income'],['4010','Rental Commission','income'],['4020','Mortgage Commission','income'],['5000','Salaries','expense'],['5010','Office Rent','expense'],['5090','Other Expense','expense']]; foreach($defs as [$c,$n,$t]) Account::withoutGlobalScopes()->firstOrCreate(['agency_id'=>$agency->id,'code'=>$c],['name'=>$n,'type'=>$t,'currency'=>'AFN','is_system'=>1,'is_active'=>1]); }
 public function post(int $agencyId,string $description,array $lines,string $sourceType='manual',?int $sourceId=null):JournalEntry { return DB::transaction(function()use($agencyId,$description,$lines,$sourceType,$sourceId){$debit=array_sum(array_column($lines,'debit'));$credit=array_sum(array_column($lines,'credit'));if(round($debit-$credit,2)!==0.0) throw new \InvalidArgumentException('Journal entry is not balanced.'); $entry=JournalEntry::withoutGlobalScopes()->create(['agency_id'=>$agencyId,'entry_no'=>'JE-'.date('YmdHis').'-'.random_int(100,999),'entry_date'=>now()->toDateString(),'description'=>$description,'source_type'=>$sourceType,'source_id'=>$sourceId,'status'=>'posted','posted_by'=>auth()->id()]); foreach($lines as $line){JournalLine::withoutGlobalScopes()->create(['agency_id'=>$agencyId,'journal_entry_id'=>$entry->id,'account_id'=>$line['account_id'],'debit'=>$line['debit']??0,'credit'=>$line['credit']??0,'currency'=>$line['currency']??'AFN','exchange_rate_to_afn'=>$line['exchange_rate_to_afn']??1,'memo'=>$line['memo']??null]);} return $entry;}); }
}
